using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Provides web search capability to the research agent.
/// Uses the Brave Search API when configured, otherwise returns simulated results.
/// </summary>
public sealed class WebSearchTool(IHttpClientFactory httpClientFactory, ILogger<WebSearchTool> logger)
{
    [Description("Searches the web for information on a given query and returns relevant results. " +
                 "Use this tool to find facts, articles, and data about any topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching the web for: {Query}", query);

        maxResults = Math.Clamp(maxResults, 1, 10);

        var apiKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
        if (!string.IsNullOrEmpty(apiKey))
        {
            return await SearchWithBraveAsync(query, maxResults, apiKey, cancellationToken);
        }

        logger.LogWarning("BRAVE_SEARCH_API_KEY not set — returning simulated search results");
        return GetSimulatedResults(query);
    }

    private async Task<string> SearchWithBraveAsync(
        string query, int maxResults, string apiKey, CancellationToken cancellationToken)
    {
        var client = httpClientFactory.CreateClient("BraveSearch");
        var encodedQuery = WebUtility.UrlEncode(query);
        var url = $"https://api.search.brave.com/res/v1/web/search?q={encodedQuery}&count={maxResults}";

        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("Accept", "application/json");
        request.Headers.Add("X-Subscription-Token", apiKey);

        using var response = await client.SendAsync(request, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        var doc = JsonDocument.Parse(json);

        var results = new List<string>();
        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var webResults))
        {
            foreach (var result in webResults.EnumerateArray())
            {
                var title = result.GetProperty("title").GetString();
                var description = result.TryGetProperty("description", out var desc)
                    ? desc.GetString() : "No description";
                var resultUrl = result.GetProperty("url").GetString();

                results.Add($"Title: {title}\nURL: {resultUrl}\nSnippet: {description}");
            }
        }

        return results.Count > 0
            ? string.Join("\n---\n", results)
            : "No results found.";
    }

    private static string GetSimulatedResults(string query)
    {
        return $"""
            [Simulated search results for "{query}"]
            ---
            Title: Overview of {query} — Wikipedia
            URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
            Snippet: {query} is a broad topic encompassing many areas of study. Recent developments have expanded our understanding significantly.
            ---
            Title: Latest Research on {query} — ScienceDaily
            URL: https://www.sciencedaily.com/search/?keyword={Uri.EscapeDataString(query)}
            Snippet: Researchers have made new breakthroughs related to {query}, publishing findings in leading journals.
            ---
            Title: {query}: A Comprehensive Guide — Britannica
            URL: https://www.britannica.com/search?query={Uri.EscapeDataString(query)}
            Snippet: This guide covers the history, key concepts, and modern applications of {query}.
            """;
    }
}

using System.ComponentModel;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capability to the research agent.
/// Stores and retrieves notes organized by topic during a research session.
/// </summary>
public sealed class NotesTool(ILogger<NotesTool> logger)
{
    private readonly Dictionary<string, List<string>> _notes = new(StringComparer.OrdinalIgnoreCase);

    [Description("Saves a research note under a given topic heading. " +
                 "Use this to record key facts, findings, or insights discovered during research.")]
    public string SaveNote(
        [Description("The topic or category for this note (e.g., 'History', 'Key Findings')")] string topic,
        [Description("The content of the note to save")] string content)
    {
        if (!_notes.TryGetValue(topic, out var topicNotes))
        {
            topicNotes = [];
            _notes[topic] = topicNotes;
        }

        topicNotes.Add(content);
        logger.LogInformation("Saved note under '{Topic}' ({Count} notes total)", topic, topicNotes.Count);

        return $"Note saved under '{topic}'. You now have {topicNotes.Count} note(s) in this topic.";
    }

    [Description("Retrieves all saved notes, organized by topic. " +
                 "Use this before writing a summary to review everything you've collected.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sections = new List<string>();
        foreach (var (topic, notes) in _notes.OrderBy(kv => kv.Key))
        {
            var numberedNotes = notes.Select((n, i) => $"  {i + 1}. {n}");
            sections.Add($"## {topic}\n{string.Join("\n", numberedNotes)}");
        }

        logger.LogInformation("Retrieved {TopicCount} topics with {NoteCount} total notes",
            _notes.Count, _notes.Values.Sum(n => n.Count));

        return string.Join("\n\n", sections);
    }

    [Description("Lists all topic headings that have saved notes.")]
    public string ListTopics()
    {
        if (_notes.Count == 0)
        {
            return "No topics yet.";
        }

        var topics = _notes.Select(kv => $"- {kv.Key} ({kv.Value.Count} notes)");
        return "Topics:\n" + string.Join("\n", topics);
    }
}

