using System.ComponentModel;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capability to the research agent.
/// Stores and retrieves notes organized by topic during a research session.
/// </summary>
public sealed class NotesTool(ILogger<NotesTool> logger)
{
    private readonly Dictionary<string, List<string>> _notes = new(StringComparer.OrdinalIgnoreCase);

    [Description("Saves a research note under a given topic heading. " +
                 "Use this to record key facts, findings, or insights discovered during research.")]
    public string SaveNote(
        [Description("The topic or category for this note (e.g., 'History', 'Key Findings')")] string topic,
        [Description("The content of the note to save")] string content)
    {
        if (!_notes.TryGetValue(topic, out var topicNotes))
        {
            topicNotes = [];
            _notes[topic] = topicNotes;
        }

        topicNotes.Add(content);
        logger.LogInformation("Saved note under '{Topic}' ({Count} notes total)", topic, topicNotes.Count);

        return $"Note saved under '{topic}'. You now have {topicNotes.Count} note(s) in this topic.";
    }

    [Description("Retrieves all saved notes, organized by topic. " +
                 "Use this before writing a summary to review everything you've collected.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sections = new List<string>();
        foreach (var (topic, notes) in _notes.OrderBy(kv => kv.Key))
        {
            var numberedNotes = notes.Select((n, i) => $"  {i + 1}. {n}");
            sections.Add($"## {topic}\n{string.Join("\n", numberedNotes)}");
        }

        logger.LogInformation("Retrieved {TopicCount} topics with {NoteCount} total notes",
            _notes.Count, _notes.Values.Sum(n => n.Count));

        return string.Join("\n\n", sections);
    }

    [Description("Lists all topic headings that have saved notes.")]
    public string ListTopics()
    {
        if (_notes.Count == 0)
        {
            return "No topics yet.";
        }

        var topics = _notes.Select(kv => $"- {kv.Key} ({kv.Value.Count} notes)");
        return "Topics:\n" + string.Join("\n", topics);
    }
}

