using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

// --- Dependency injection setup ---
var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Information));

services.AddHttpClient();

services.AddSingleton<NotesTool>();
services.AddSingleton<WebSearchTool>();

services.AddChatClient(builder => builder
    .UseLogging()
    .Use(new OpenAIClient(new ApiKeyCredential(apiKey))
        .GetChatClient(modelId)));

await using var sp = services.BuildServiceProvider();

var chatClient = sp.GetRequiredService<IChatClient>();
var notesTool = sp.GetRequiredService<NotesTool>();
var searchTool = sp.GetRequiredService<WebSearchTool>();
var logger = sp.GetRequiredService<ILogger<Program>>();

// --- Build the agent with tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(notesTool.SaveNote),
    AIFunctionFactory.Create(notesTool.GetAllNotes),
    AIFunctionFactory.Create(notesTool.ListTopics),
};

const string instructions = """
    You are a research agent. Your job is to thoroughly research a topic provided by the user.

    Follow this process:
    1. Search the web for the topic using multiple targeted queries to cover different angles.
    2. As you find relevant information, save detailed notes using the note-taking tool,
       organizing them under clear topic headings.
    3. After gathering enough information (at least 3 searches), retrieve all your notes.
    4. Provide a well-structured summary of your findings, citing the sources you found.

    Be thorough but focused. Save the most important facts and findings as notes.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools",
    tools: tools);

// --- Get the research topic ---
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('=', 60));

// --- Run the agent with streaming ---
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

try
{
    await foreach (var update in agent.RunStreamingAsync(
        $"Research the following topic and provide a comprehensive summary: {topic}",
        options: runOptions))
    {
        if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine(new string('=', 60));
    Console.WriteLine("Research complete.");
}
catch (Exception ex)
{
    logger.LogError(ex, "Agent execution failed");
    Console.WriteLine($"\nError: {ex.Message}");
}

